const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const categories={sedan:{label:'CATEGORIA EXECUTIVA',title:'Elegância.<br>Em cada chegada.',description:'Uma opção para deslocamentos individuais e agendas executivas, com conforto e atenção ao seu percurso.',image:'sedan.png',name:'Sedan'},suv:{label:'ESPAÇO PARA SEUS PLANOS',title:'Mais espaço.<br>O mesmo cuidado.',description:'Uma categoria versátil para quem busca espaço e conforto. Consulte a configuração adequada aos passageiros e às bagagens.',image:'suv.webp',name:'SUV'},blindado:{label:'ATENDIMENTO ESPECIALIZADO',title:'Sua necessidade.<br>Nossa atenção.',description:'Conte sua demanda à equipe para receber orientação sobre veículos blindados e confirmar as opções disponíveis.',image:'suv.webp',name:'Blindado'},van:{label:'VIAJE EM BOA COMPANHIA',title:'Juntos.<br>Do início ao destino.',description:'Transporte para grupos, equipes e convidados. A equipe orienta o veículo e a configuração conforme a sua demanda.',image:'experiencia.jpg',name:'Van',photo:true},grupo:{label:'LOGÍSTICA PARA GRUPOS',title:'Grandes encontros.<br>Caminhos organizados.',description:'Ônibus e micro-ônibus para demandas de grupos. Compartilhe o roteiro e a quantidade de passageiros para planejar o atendimento.',image:'onibus.jpg',name:'Ônibus ou micro-ônibus',photo:true}};let selected='sedan';document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.category;const c=categories[selected];document.querySelectorAll('[data-category]').forEach(b=>{b.setAttribute('aria-selected',b===button);b.tabIndex=b===button?0:-1});document.querySelector('#fleet-label').textContent=c.label;document.querySelector('#fleet-title').innerHTML=c.title;document.querySelector('#fleet-description').textContent=c.description;const img=document.querySelector('#fleet-image');img.src='assets/'+c.image;img.alt='Imagem ilustrativa da categoria '+c.name+(selected==='blindado'?' — blindagem a confirmar com a equipe':'');img.classList.toggle('photo',!!c.photo);document.querySelector('[name=categoria]').value=c.name}));document.querySelectorAll('[role=tab]').forEach(b=>b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')];let i=tabs.indexOf(b);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click()}));
const descriptions={'Transporte executivo':'Para reuniões, compromissos profissionais e agendas que pedem atenção aos detalhes. Compartilhe os locais, os horários e a quantidade de passageiros. A equipe PTE orienta a categoria adequada e confirma a disponibilidade.','Transfers e viagens':'Organize sua chegada, partida ou viagem com atendimento pessoal. Informe origem, destino, data, horários e bagagens para alinhar o trajeto com a equipe.','Eventos e grupos':'Da movimentação de convidados à logística de equipes e artistas, cada demanda tem suas particularidades. Conte os locais, horários e o tamanho do grupo para receber orientação sobre veículos e atendimento.'};const dialog=document.querySelector('dialog');document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dialog-title').textContent=b.dataset.service;document.querySelector('#dialog-description').textContent=descriptions[b.dataset.service];dialog.showModal()}));document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#dialog-cta').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('[name=data]').min=new Date().toLocaleDateString('en-CA');document.querySelector('#trip-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const date=f.get('data').split('-').reverse().join('/');const text=`Olá, equipe PTE! Meu nome é ${f.get('nome')}. Gostaria de planejar um atendimento.\n\nOrigem: ${f.get('origem')}\nDestino: ${f.get('destino')}\nData: ${date}\nPassageiros: ${f.get('passageiros')}\nCategoria: ${f.get('categoria')}\nDetalhes: ${f.get('detalhes')||'A combinar'}\n\nPodem me orientar sobre disponibilidade?`;window.open('https://wa.me/558192924800?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.service,.experience-copy,.process-grid,.faq').forEach((el,i)=>{el.classList.add('reveal');observer.observe(el)});
